module coexistence_check (\n    input clk, rst_n, start,\n    input [3:0] edge_count,\n    input [4:0] edge_i_j [0:15],\n    output reg result, done\n);\n    \n    // State declarations\n    localparam [1:0] IDLE   = 2'd0;\n    localparam [1:0] LOAD   = 2'd1;\n    localparam [1:0] CHECK  = 2'd2;\n    localparam [1:0] DONE   = 2'd3;\n    \n    // Register declarations\n    reg [1:0] state;\n    reg [3:0] current_edge;\n    reg [3:0] edge_index;\n    reg [3:0] queue [0:15];\n    reg [3:0] queue_head;\n    reg [3:0] queue_tail;\n    reg [3:0] color [0:15];\n    reg [15:0] visited;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n    \n    // Initialize all registers\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current_edge <= 4'd0;\n            edge_index <= 4'd0;\n            queue_head <= 4'd0;\n            queue_tail <= 4'd0;\n            result <= 1'b0;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n            \n            // Initialize color array\n            integer i;\n            for (i = 0; i < 16; i = i + 1) begin\n                color[i] <= 2'd0;\n            end\n            \n            // Initialize visited array\n            visited <= 16'd0;\n            \n            // Initialize queue\n            for (i = 0; i < 16; i = i + 1) begin\n                queue[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        state <= LOAD;\n                    end\n                end\n                \n                LOAD: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    \n                    // Initialize color and visited arrays\n                    integer i;\n                    for (i = 0; i < 16; i = i + 1) begin\n                        color[i] <= 2'd0;\n                    end\n                    visited <= 16'd0;\n                    \n                    // Initialize queue\n                    queue_head <= 4'd0;\n                    queue_tail <= 4'd0;\n                    for (i = 0; i < 16; i = i + 1) begin\n                        queue[i] <= 4'd0;\n                    end\n                    \n                    // Start with first edge\n                    edge_index <= 4'd0;\n                    state <= CHECK;\n                end\n                \n                CHECK: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    \n                    // Check if all edges processed\n                    if (edge_index >= edge_count) begin\n                        result <= 1'b1;  // Bipartite\n                        state <= DONE;\n                    end else begin\n                        // Get current edge\n                        current_edge <= edge_i_j[edge_index];\n                        reg [1:0] i = current_edge[4:2];\n                        reg [1:0] j = current_edge[1:0];\n                        \n                        // Check if both islands are unvisited\n                        if (!visited[i] && !visited[j]) begin\n                            // Assign colors\n                            color[i] <= 2'd0;\n                            color[j] <= 2'd1;\n                            visited[i] <= 1'b1;\n                            visited[j] <= 1'b1;\n                            \n                            // Add to queue\n                            queue[queue_tail] <= i;\n                            queue_tail <= queue_tail + 4'd1;\n                            queue[queue_tail] <= j;\n                            queue_tail <= queue_tail + 4'd1;\n                        end\n                        \n                        // Check if one island is visited\n                        else if (visited[i] && !visited[j]) begin\n                            // Assign opposite color\n                            color[j] <= ~color[i];\n                            visited[j] <= 1'b1;\n                            \n                            // Add to queue\n                            queue[queue_tail] <= j;\n                            queue_tail <= queue_tail + 4'd1;\n                        end\n                        \n                        // Check if other island is visited\n                        else if (!visited[i] && visited[j]) begin\n                            // Assign opposite color\n                            color[i] <= ~color[j];\n                            visited[i] <= 1'b1;\n                            \n                            // Add to queue\n                            queue[queue_tail] <= i;\n                            queue_tail <= queue_tail + 4'd1;\n                        end\n                        \n                        // Check if both islands are visited\n                        else if (visited[i] && visited[j]) begin\n                            // Check for conflict\n                            if (color[i] == color[j]) begin\n                                result <= 1'b0;  // Not bipartite\n                                state <= DONE;\n                            end\n                        end\n                        \n                        // Move to next edge\n                        edge_index <= edge_index + 4'd1;\n                    end\n                    \n                    // Check for cycle limit\n                    if (cycle_count >= MAX_CYCLES) begin\n                        result <= 1'b0;  // Timeout\n                        state <= DONE;\n                    end\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule